function pefDb(?string $name = null): mysqli { $d=new mysqli(getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1',getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root',getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_demo_local',$name,(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306));$d->set_charset('utf8mb4');return $d; }
function pefPort(): int { $s=stream_socket_server('tcp://127.0.0.1:0',$e,$m);if($s===false)throw new TestFailure('allocate HTTP port');$n=(string)stream_socket_get_name($s,false);fclose($s);return (int)substr($n,strrpos($n,':')+1); }
function pefStart(array $env): array { $p=pefPort();$c=['/usr/bin/env','-i'];foreach($env as$k=>$v)$c[]="$k=$v";$c=[...$c,PHP_BINARY,'-d','expose_php=0','-S',"127.0.0.1:$p",dirname(__DIR__,2).'/public/router.php'];$r=proc_open($c,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__,2));if(!is_resource($r))throw new TestFailure('start production HTTP');fclose($pipes[0]);$until=microtime(true)+5;do{$s=@stream_socket_client("tcp://127.0.0.1:$p",$e,$m,.1);if($s!==false){fclose($s);return ['process'=>$r,'pipes'=>$pipes,'port'=>$p];}usleep(50000);}while(microtime(true)<$until);throw new TestFailure('production HTTP did not listen'); }
function pefStop(?array $s): void { if($s===null)return;if(proc_get_status($s['process'])['running'])proc_terminate($s['process']);foreach([1,2]as$i){stream_get_contents($s['pipes'][$i]);fclose($s['pipes'][$i]);}proc_close($s['process']); }
function pefRequest(int $port,string $method,string $target,array $headers=[],string $body=''): array { $s=stream_socket_client("tcp://127.0.0.1:$port",$e,$m,5);if($s===false)throw new TestFailure('connect HTTP');$w="$method $target HTTP/1.1\r\nHost: pilot.example\r\nConnection: close\r\n";foreach($headers as$k=>$v)$w.="$k: $v\r\n";fwrite($s,$w."\r\n".$body);stream_socket_shutdown($s,STREAM_SHUT_WR);$raw='';while(!feof($s)){$x=fread($s,65536);if($x===false)break;$raw.=$x;}fclose($s);[$h,$b]=array_pad(explode("\r\n\r\n",$raw,2),2,'');$ls=explode("\r\n",$h);preg_match('/^HTTP\/\d\.\d (\d{3})/',(string)array_shift($ls),$mm);$hs=[];foreach($ls as$l)if(str_contains($l,':')){[$k,$v]=explode(':',$l,2);$hs[strtolower(trim($k))][]=trim($v);}return ['status'=>(int)($mm[1]??0),'headers'=>$hs,'body'=>$b]; }
function pefHeader(array $r,string $n): ?string { $v=$r['headers'][strtolower($n)]??[];return count($v)===1?$v[0]:null; }
function pefXpath(string $html): DOMXPath { $d=new DOMDocument();$old=libxml_use_internal_errors(true);$ok=$d->loadHTML($html,LIBXML_NONET|LIBXML_NOERROR|LIBXML_NOWARNING);libxml_clear_errors();libxml_use_internal_errors($old);assertSameValue(true,$ok,'response is HTML');return new DOMXPath($d); }
function pefValue(DOMXPath $xp,string $name): string { $n=$xp->query("//input[@name='$name']");assertSameValue(1,$n->length,"one $name control");return $n->item(0)->getAttribute('value'); }
function pefCookie(array $r): string { $h=pefHeader($r,'set-cookie');assertSameValue(true,is_string($h),'command page creates pilot cookie');assertSameValue(true,str_contains($h,'Secure')&&str_contains($h,'HttpOnly')&&str_contains($h,'SameSite=Strict')&&str_contains($h,'Path=/pilot'),'secure pilot cookie');return explode(';',$h,2)[0]; }
function pefPost(int $p,string $path,string $cookie,array $fields): array { $body=http_build_query($fields,'','&',PHP_QUERY_RFC3986);return pefRequest($p,'POST',$path,['Cookie'=>$cookie,'Origin'=>'https://pilot.example','Sec-Fetch-Site'=>'same-origin','Content-Type'=>'application/x-www-form-urlencoded; charset=UTF-8','Content-Length'=>(string)strlen($body)],$body); }
function pef303(array $r,string $location,string $why): void { assertSameValue(303,$r['status'],$why.' status');assertSameValue($location,pefHeader($r,'location'),$why.' canonical location');assertSameValue('0',pefHeader($r,'content-length'),$why.' zero length');assertSameValue('',$r['body'],$why.' empty body'); }
function pefText(array $r,string $literal,string $why): void { assertSameValue(true,str_contains(preg_replace('/\s+/u',' ',strip_tags($r['body']))??'',$literal),$why.' visible '.$literal); }

